INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `badge`, `concentration`, `gender`, `scent_family`, `short_description`, `description`, `top_notes`, `middle_notes`, `base_notes`, `longevity`, `sillage`, `projection`, `mood`, `price`, `original_price`, `discount_percent`, `stock`, `is_sold_out`, `rating`, `reviews_count`, `image`, `gallery`, `is_featured`, `is_popular`, `is_bestseller`, `is_active`, `created_at`, `updated_at`) VALUES ('1', '4', 'Mykonos x SetiawanAde - Glitch Extrait de Parfum 50ml & 100ml', 'mykonos-x-setiawanade-glitch', '-52%', 'Extrait de Parfum', 'unisex', 'Gourmand Metallic Amber', 'Kolaborasi fenomenal dengan arsitektur aroma futuristik, perpaduan bergamot renyah, heliotrope, dan ambery tonka yang adiktif.', 'Glitch lahir dari imajinasi masa depan yang menembus batas olfaktori. Dibuka dengan sentuhan Italian Bergamot yang menyegarkan berpadu kilatan aldehid modern, kemudian bertransisi menjadi harmoni lavender lembut dan sentuhan metallic accord yang memikat. Dasarnya ditopang oleh Ambergris pekat, Tonka Bean manis hangat, dan Oakmoss yang memberikan ketahanan luar biasa hingga 14 jam.', 'Italian Bergamot, Pink Pepper, Clean Aldehydes', 'French Lavender, Metallic Accord, Violet Leaf, Cedarwood', 'Ambergris, Roasted Tonka Bean, Oakmoss, Clean White Musk', '12 - 14 Jam', 'Strong (Radius 2-3 Meter)', 'Kuat & Mengisi Ruangan', 'Futuristik, Percaya Diri, Magnetik, Misterius', '239000', '499000', '52', '85', '0', '4.9', '1420', 'images/product-glitch.png', NULL, '1', '1', '1', '1', '2026-10-19 03:47:11', '2026-10-19 03:47:11');
INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `badge`, `concentration`, `gender`, `scent_family`, `short_description`, `description`, `top_notes`, `middle_notes`, `base_notes`, `longevity`, `sillage`, `projection`, `mood`, `price`, `original_price`, `discount_percent`, `stock`, `is_sold_out`, `rating`, `reviews_count`, `image`, `gallery`, `is_featured`, `is_popular`, `is_bestseller`, `is_active`, `created_at`, `updated_at`) VALUES ('2', '2', 'Mykonos - Royal Ispahan Extrait de Parfum 50ml & 100ml', 'mykonos-royal-ispahan', 'Terjual habis', 'Extrait de Parfum', 'women', 'Floral Oriental Luxury', 'Kemegahan mawar Ispahan Persia berpadu kelembutan leci manis dan vanila Bourbon yang mewah.', 'Royal Ispahan adalah perwujudan keanggunan ratu istana timur. Mawar Damaskus terbaik dipadukan dengan manisnya buah leci ranum dan sentuhan dupa mistis. Pada fase akhir, Madagascar Vanilla dan Ambergris menyatu membentuk jejak aroma manis yang memabukkan dan tahan seharian penuh.', 'Turkish Rose, Candied Lychee, Bergamot', 'Damascus Rose, Peony, Incense, Cedar', 'Madagascar Vanilla, Light Oud, Ambergris, Cashmeran', '14 - 16 Jam', 'Enormous (Jejak aroma sangat panjang)', 'Sangat Kuat', 'Glamour, Romantis, Elegan, Berkelas', '449000', '449000', NULL, '0', '1', '5', '890', 'images/product-royal-ispahan.png', NULL, '1', '1', '0', '1', '2026-10-19 03:47:11', '2026-10-19 03:47:11');
INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `badge`, `concentration`, `gender`, `scent_family`, `short_description`, `description`, `top_notes`, `middle_notes`, `base_notes`, `longevity`, `sillage`, `projection`, `mood`, `price`, `original_price`, `discount_percent`, `stock`, `is_sold_out`, `rating`, `reviews_count`, `image`, `gallery`, `is_featured`, `is_popular`, `is_bestseller`, `is_active`, `created_at`, `updated_at`) VALUES ('3', '2', 'Mykonos - Baby Love EDP 50ml', 'mykonos-baby-love-edp', 'Terjual habis', 'Eau de Parfum', 'women', 'Soft Powdery Floral', 'Aroma kelembutan bedak bayi mewah nan menenangkan, bersih, hangat, dan membuat siapapun merasa nyaman.', 'Baby Love adalah wewangian nostaljik yang membawa ketenangan hati. Sentuhan bunga Violet dan Chamomile berpadu dengan bedak talek halus serta White Musk yang lembut seperti pelukan hangat di sore hari.', 'Violet, Italian Mandarin, Soft Bergamot', 'Chamomile Blossoms, Turkish Rose, Iris Butter', 'Warm Powdery Notes, White Musk, Vanilla Pods, Cedarwood', '8 - 10 Jam', 'Moderate & Intimate', 'Lembut Menenangkan', 'Comforting, Pure, Calming, Nostalgic', '449000', '449000', NULL, '0', '1', '4.8', '640', 'images/product-baby-love.png', NULL, '0', '1', '0', '1', '2026-10-19 03:47:12', '2026-10-19 03:47:12');
INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `badge`, `concentration`, `gender`, `scent_family`, `short_description`, `description`, `top_notes`, `middle_notes`, `base_notes`, `longevity`, `sillage`, `projection`, `mood`, `price`, `original_price`, `discount_percent`, `stock`, `is_sold_out`, `rating`, `reviews_count`, `image`, `gallery`, `is_featured`, `is_popular`, `is_bestseller`, `is_active`, `created_at`, `updated_at`) VALUES ('4', '1', 'Mykonos Sunforged - Imperium Extrait de Parfum', 'mykonos-sunforged-imperium', 'Signature Lion', 'Extrait de Parfum', 'men', 'Citrus Woody Aromatic', 'Lambang keagungan Singa Emas, perpaduan sitrus segar bergamot Sisilia, rempah kapulaga, dan kayu cendana ningrat.', 'Imperium diciptakan untuk pria yang memimpin dengan kharisma alami. Botol emas bersimbol singa perkasa ini menyimpan kesegaran sitrus Mediterania di lapis awal, disusul kapulaga pedas hangat dan ditutup oleh kayu cendana serta amber kaya nuansa.', 'Sicilian Bergamot, Calabrian Lemon, Zesty Grapefruit', 'French Lavender, Cardamom, Aquatic Accord, Pink Pepper', 'Ambergris, Haitian Vetiver, Mysore Sandalwood, Oakmoss', '12 - 14 Jam', 'Strong', 'Radius 2 Meter', 'Pemimpin, Karismatik, Sukses, Berwibawa', '349000', '429000', '18', '45', '0', '4.9', '1120', 'images/product-imperium.png', NULL, '1', '1', '1', '1', '2026-10-19 03:47:13', '2026-10-19 03:47:13');
INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `badge`, `concentration`, `gender`, `scent_family`, `short_description`, `description`, `top_notes`, `middle_notes`, `base_notes`, `longevity`, `sillage`, `projection`, `mood`, `price`, `original_price`, `discount_percent`, `stock`, `is_sold_out`, `rating`, `reviews_count`, `image`, `gallery`, `is_featured`, `is_popular`, `is_bestseller`, `is_active`, `created_at`, `updated_at`) VALUES ('5', '1', 'Mykonos Sunforged - Inferno Extrait de Parfum', 'mykonos-sunforged-inferno', 'Bold Dragon', 'Extrait de Parfum', 'men', 'Spicy Smoky Oriental', 'Kekuatan Naga Hitam yang menyala, ledakan saffron berasap, ceri hitam pekat, daun tembakau cerutu, dan kulit mewah.', 'Inferno adalah aroma api gairah malam yang mendebarkan. Perpaduan manis gelap Black Cherry dengan kepulan rempah saffron dan kayu manis, disempurnakan oleh kulit Tuscan dan Bourbon Vanilla yang sangat memikat.', 'Smoked Saffron, Dark Black Cherry, Indonesian Nutmeg', 'Ceylon Cinnamon Bark, Rich Leather Accord, Sweet Tobacco Leaf', 'Dark Agarwood (Oud), Roasted Amber, Bourbon Vanilla, Cedarwood', '14 - 18 Jam', 'Enormous & Deep', 'Sangat Menusuk & Memikat', 'Seksi, Misterius, Kuat, Berani', '359000', '450000', '20', '30', '0', '5', '980', 'images/product-inferno.png', NULL, '1', '1', '1', '1', '2026-10-19 03:47:13', '2026-10-19 03:47:13');
INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `badge`, `concentration`, `gender`, `scent_family`, `short_description`, `description`, `top_notes`, `middle_notes`, `base_notes`, `longevity`, `sillage`, `projection`, `mood`, `price`, `original_price`, `discount_percent`, `stock`, `is_sold_out`, `rating`, `reviews_count`, `image`, `gallery`, `is_featured`, `is_popular`, `is_bestseller`, `is_active`, `created_at`, `updated_at`) VALUES ('6', '1', 'Mykonos Sunforged - Marbella Extrait de Parfum', 'mykonos-sunforged-marbella', 'Rose Gold Phoenix', 'Extrait de Parfum', 'women', 'Fruity Floral Gourmand', 'Keindahan burung Phoenix tembaga, pesta buah berry manis, nektar persik, dan lelehan krim karamel vanila.', 'Marbella menangkap kehangatan senja musim panas di pesisir Mediterania. Stroberi liar dan nektar peach bertemu dengan keharuman bunga melati dan peony, diakhiri dengan krim vanila kocok yang adiktif.', 'Wild Strawberry, Sweet Raspberry, Spanish Peach Nectar', 'Pink Peony, Jasmine Sambac, Melted Caramel Sugar', 'Whipped Vanilla Cream, White Amber, Soft Cedarwood', '12 - 14 Jam', 'Strong & Sweet', 'Manis Semerbak', 'Playful, Ceria, Mempesona, Manis Mewah', '349000', '429000', '18', '40', '0', '4.9', '1050', 'images/product-marbella.png', NULL, '1', '1', '0', '1', '2026-10-19 03:47:14', '2026-10-19 03:47:14');
INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `badge`, `concentration`, `gender`, `scent_family`, `short_description`, `description`, `top_notes`, `middle_notes`, `base_notes`, `longevity`, `sillage`, `projection`, `mood`, `price`, `original_price`, `discount_percent`, `stock`, `is_sold_out`, `rating`, `reviews_count`, `image`, `gallery`, `is_featured`, `is_popular`, `is_bestseller`, `is_active`, `created_at`, `updated_at`) VALUES ('7', '1', 'Mykonos Sunforged - Nautilus Extrait de Parfum', 'mykonos-sunforged-nautilus', 'Ocean Seahorse', 'Extrait de Parfum', 'unisex', 'Marine Salty Fresh Aquatic', 'Kedalaman samudra dalam botol biru safir, butiran garam laut, daun sage, jeruk nipis, dan lumut laut segar.', 'Nautilus adalah hembusan angin samudra yang murni dan menyegarkan jiwa. Butiran garam laut yang renyah berpadu dengan mint dingin dan sage aromatik, didukung oleh kayu apung dan amber abu-abu yang elegan.', 'Sea Salt Crystals, Oceanic Breeze, Crisp Garden Mint, Kaffir Lime', 'Sea Driftwood, Clary Sage, Mineral Amber, Cardamom', 'Grey Ambergris, Blue Cypress, Sea Moss, Clean Musk', '10 - 12 Jam', 'Strong & Refreshing', 'Segar & Bersih', 'Bebas, Energik, Menyegarkan, Modern', '349000', '429000', '18', '35', '0', '4.8', '720', 'images/product-nautilus.png', NULL, '1', '0', '0', '1', '2026-10-19 03:47:17', '2026-10-19 03:47:17');
INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `badge`, `concentration`, `gender`, `scent_family`, `short_description`, `description`, `top_notes`, `middle_notes`, `base_notes`, `longevity`, `sillage`, `projection`, `mood`, `price`, `original_price`, `discount_percent`, `stock`, `is_sold_out`, `rating`, `reviews_count`, `image`, `gallery`, `is_featured`, `is_popular`, `is_bestseller`, `is_active`, `created_at`, `updated_at`) VALUES ('8', '1', 'Mykonos Sunforged - Untamed Extrait de Parfum', 'mykonos-sunforged-untamed', 'Wild Spirit', 'Extrait de Parfum', 'unisex', 'Ambery Spicy Coffee Leather', 'Semangat kuda liar yang bebas, biji kopi arabika panggang, rum manis berumur, tonka bean, dan kayu cendana.', 'Untamed merefleksikan jiwa petualang yang tak kenal takut. Aroma seduhan kopi hitam pekat dengan sentuhan tetesan rum hangat dan blood orange segar, bertransformasi menjadi kehangatan kayu dan amber kristal yang menawan.', 'Sicilian Blood Orange, Cardamom, Sweet Elemi Resin', 'Dark Roasted Arabica Coffee, Tonka Beans, Aged Dark Rum Accord', 'Warm Australian Sandalwood, Dark Patchouli, Golden Amber', '14 - 16 Jam', 'Enormous', 'Sangat Berkarakter', 'Petualang, Liar, Hangat, Karismatik', '369000', '450000', '18', '28', '0', '4.9', '860', 'images/product-untamed.png', NULL, '1', '1', '1', '1', '2026-10-19 03:47:18', '2026-10-19 03:47:18');
