INSERT INTO `reviews` (`id`, `product_id`, `customer_name`, `rating`, `comment`, `variant_size`, `is_verified_buyer`, `created_at`, `updated_at`) VALUES ('1', '1', 'Aditya Pratama', '5', 'Parfum lokal terbaik yang pernah saya beli! Wanginya mewah banget, mirip niche perfume jutaan rupiah. Ketahanan 12 jam di baju masih kecium.', '100ml', '1', '2026-10-19 03:47:11', '2026-10-19 03:47:11');
INSERT INTO `reviews` (`id`, `product_id`, `customer_name`, `rating`, `comment`, `variant_size`, `is_verified_buyer`, `created_at`, `updated_at`) VALUES ('2', '1', 'Farhan Nugraha', '5', 'Diskon 52% langsung checkout tanpa mikir. Wangi Glitch ini khas banget, orang kantor pada nanya pake parfum apa.', '50ml', '1', '2026-10-19 03:47:11', '2026-10-19 03:47:11');
INSERT INTO `reviews` (`id`, `product_id`, `customer_name`, `rating`, `comment`, `variant_size`, `is_verified_buyer`, `created_at`, `updated_at`) VALUES ('3', '1', 'Jessica Tanuwijaya', '5', 'Beli buat kado pacar, tapi malah sering saya pake sendiri karena unisex dan baunya enak banget saat drydown!', '50ml', '1', '2026-10-19 03:47:11', '2026-10-19 03:47:11');
INSERT INTO `reviews` (`id`, `product_id`, `customer_name`, `rating`, `comment`, `variant_size`, `is_verified_buyer`, `created_at`, `updated_at`) VALUES ('4', '2', 'Clarissa Putri', '5', 'Kapan restock min? Wanginya beneran rose oud terenak se-Indonesia, gak nusuk hidung sama sekali.', '50ml', '1', '2026-10-19 03:47:12', '2026-10-19 03:47:12');
INSERT INTO `reviews` (`id`, `product_id`, `customer_name`, `rating`, `comment`, `variant_size`, `is_verified_buyer`, `created_at`, `updated_at`) VALUES ('5', '2', 'Dewi Anggraini', '5', 'Juara! Pakai ini buat kondangan malem, wanginya nempel sampe besok paginya.', '100ml', '1', '2026-10-19 03:47:12', '2026-10-19 03:47:12');
INSERT INTO `reviews` (`id`, `product_id`, `customer_name`, `rating`, `comment`, `variant_size`, `is_verified_buyer`, `created_at`, `updated_at`) VALUES ('6', '3', 'Nabila Syakieb', '5', 'Wangi bayi paling berkelas! Gak kayak minyak telon, tapi bener-bener parfum mahal.', '50ml', '1', '2026-10-19 03:47:13', '2026-10-19 03:47:13');
INSERT INTO `reviews` (`id`, `product_id`, `customer_name`, `rating`, `comment`, `variant_size`, `is_verified_buyer`, `created_at`, `updated_at`) VALUES ('7', '4', 'Bambang Soebroto', '5', 'Botol emasnya beneran berat dan mewah banget. Wanginya maskulin dan tahan dari pagi sampe malem di ruangan ber-AC.', '100ml', '1', '2026-10-19 03:47:13', '2026-10-19 03:47:13');
INSERT INTO `reviews` (`id`, `product_id`, `customer_name`, `rating`, `comment`, `variant_size`, `is_verified_buyer`, `created_at`, `updated_at`) VALUES ('8', '5', 'Rian Hidayat', '5', 'Ini parfum buat night out paling gokil. Baunya deep banget, leather dan cherry-nya balance sempurna.', '100ml', '1', '2026-10-19 03:47:14', '2026-10-19 03:47:14');
